#!/bin/sh
# get_vorbis_tools.sh -- reproducibly obtain RUNNABLE oggenc/ogginfo with NO root.
#
# Mirrors examples/z98/z9torr/tests/get_aria2.sh: uses a private, writable apt
# state/cache under $TMP, downloads vorbis-tools + its dependencies with
# `apt-get --download-only --no-install-recommends`, and unpacks every .deb into
# an extraction prefix with `dpkg-deb -x`. The `Dir::State::status` redirect
# lets apt run as an unprivileged user without writing to /var/lib/dpkg.
#
# The fixtures (tests/mkfixtures.sh) are generated by these binaries; nothing
# here is linked into the Z98 example (spec §8: fixtures are *generated*, not
# vendored).
#
# stdout (parseable lines):
#   oggenc: <path>
#   ogginfo: <path>
#   LD_LIBRARY_PATH: <colon-separated dirs>   (required for both to run)
#   oggenc_version: <first line of `oggenc --version`>
#
# Exits non-zero if oggenc/ogginfo cannot be produced or run.
#
# Usage:  TMP=/tmp/vorbis sh get_vorbis_tools.sh
#         TMP=/tmp/vorbis SYS=/tmp/vorbis/sys sh get_vorbis_tools.sh   # stable prefix
#
# POSIX sh + coreutils/GNU find + dpkg-deb + apt-get (Debian bookworm).

set -eu

TMP="${TMP:-/tmp/vorbis}"
W="${W:-$TMP/work}"
SYS="${SYS:-$TMP/sys}"
ARCH="${ARCH:-amd64}"
# The Debian release the tools are fetched from. Informational only: the
# committed .ogg fixtures (not this acquisition) are the source of truth.
DIST="${DIST:-bookworm}"

rm -rf "$W" "$SYS"
mkdir -p "$W/state/lists/partial" "$W/cache/archives/partial" "$W/etc/apt"
touch "$W/state/status"
printf 'deb [arch=%s] http://deb.debian.org/debian %s main\n' "$ARCH" "$DIST" \
    > "$W/etc/apt/sources.list"

AO="-o Dir::State=$W/state -o Dir::State::lists=$W/state/lists -o Dir::State::status=$W/state/status -o Dir::Cache=$W/cache -o Dir::Cache::archives=$W/cache/archives -o Dir::Etc::sourcelist=$W/etc/apt/sources.list -o Dir::Etc::sourceparts=/dev/null -o APT::Get::List-Cleanup=0 -o Acquire::Languages=none"

echo "== apt-get update (private state under $W) ==" >&2
apt-get $AO update >&2

echo "== apt-get install --download-only vorbis-tools ==" >&2
apt-get $AO install --download-only --no-install-recommends -y vorbis-tools >&2

mkdir -p "$SYS"
for d in "$W"/cache/archives/*.deb; do
    [ -f "$d" ] || continue
    dpkg-deb -x "$d" "$SYS"
done

OGGENC="$SYS/usr/bin/oggenc"
OGGINFO="$SYS/usr/bin/ogginfo"
for b in "$OGGENC" "$OGGINFO"; do
    if [ ! -x "$b" ]; then
        echo "get_vorbis_tools: not produced at $b" >&2
        exit 1
    fi
done

LD="$(find "$SYS" -name '*.so*' -printf '%h\n' 2>/dev/null | sort -u | tr '\n' ':')"

VER="$(env LD_LIBRARY_PATH="$LD" "$OGGENC" --version 2>&1 | head -n1)"
case "$VER" in
    *oggenc*) ;;
    *)
        echo "get_vorbis_tools: oggenc did not run (got '$VER')" >&2
        exit 1
        ;;
esac

# ogginfo has no --version; `-h` prints usage and exits 0 when it runs.
env LD_LIBRARY_PATH="$LD" "$OGGINFO" -h >/dev/null 2>&1 || {
    echo "get_vorbis_tools: ogginfo failed to run" >&2
    exit 1
}

echo "oggenc: $OGGENC"
echo "ogginfo: $OGGINFO"
echo "LD_LIBRARY_PATH: $LD"
echo "oggenc_version: $VER"
